// パス調整処理
var eirUrl = ('https:' == document.location.protocol ? 'https://ssl4' : 'http://v4') + '.eir-parts.net';

// true:訂正表示 false:訂正非表示
var teiseiFlg = true;

// 0:メニューリンク、1:プルダウン、それ以外の時は表示しない
var yearList = 2;

// true:アンカーリンク表示 false:アンカーリンク非表示(yearList;0,1以外のみに使用可能)
