// 指定されたJSON・Xmlのファイルから取得した
// データを保持する変数
var org_data;
// 年度アップローダのデータ
var org_data_2;

// 新着情報アイコンを表示するかしないかの切替フラグ
var NewIconFlg = true;
// Newアイコンが表示される上限日付(現在の日時から何日前までかを指定する)
var NewIconLimit = -"●";

// 西暦=true 和暦=false
var seiwa = true;
// 半角=true 全角=false
var z2h = true;

var total = 0;

han = new Array(" ","1","2","3","4","5","6","7","8","9","0");
zen = new Array("　","１","２","３","４","５","６","７","８","９","０");

function zen2han(text){
	if(z2h){
		for(var ii=0;ii<zen.length;ii++){
			var regex = new RegExp(zen[ii], "g");
			text = text.replace(regex, han[ii]);
		}
	}
	return text;
}

// 半角数字を全角数字に変換して返す関数
function HankakuToZenkakuNum(numStr) {
	if(z2h){
		return numStr;
	}
	var zenkaku = "０１２３４５６７８９";
	var hankaku = "0123456789";

	var retStr = "";
	for ( var i = 0; i < numStr.length; i++) {
		chr = numStr.charAt(i);
		zen = hankaku.indexOf(chr, 0);
		if (zen >= 0) {
			chr = zenkaku.charAt(zen);
		}
		retStr += chr;
	}
	return retStr;
}

// 西暦を和暦に変換して返す関数
function SeirekiToWareki(ym) {
	var year = ym.substring(0, 4);
	var month = new String(new Number(ym.substr(4, 2)));
	if(seiwa){
		if (year >= 1989) {
			return year + "年" + HankakuToZenkakuNum(month) + "月期";
		}
		return year + "年" + HankakuToZenkakuNum(month) + "月期";
	}
	else{
		if (year >= 1989) {
			if ( (year - 1988) == 1){
				return "平成元年" + HankakuToZenkakuNum(month) + "月期";
			}
			else{
				return year + "年（平成" + (year - 1988) + "年）" + HankakuToZenkakuNum(month) + "月期";
			}
		}
		return "昭和" + (year - 1925) + "年" + HankakuToZenkakuNum(month) + "月期";
	}
}

