}


//------------------------------
// 各年度のメニューリンクを作成する
//------------------------------
function CreateAnchorElm(year) {

	// 各年度のリンクを新規に作成する
	var elmAYear = document.createElement('a');

	// hrefの設定
	elmAYear.href = 'javascript:void(0);';

	// イベントハンドラを追加する
	addEventListenerIR(elmAYear, 'click', function(){ return YearLink_onclick(year); });

	// Textの設定
	elmAYear.appendChild(document.createTextNode(SeirekiToWareki(year)));

	return elmAYear;
}

//------------------------------
// 年度選択DropDownListの項目が
// 切り替えられた時のイベントハンドラ
