function YearLink_onclick(year) {

	// 表示データの更新を行う
	drawDataArea(org_data, year);

	return false;
}


//------------------------------
// JSON/Xmlから取得したデータを表示するメインAPI
//------------------------------
function drawDataArea(data, selFy) {
	// データ表示箇所のルートElementを取得する
	var elmDiv = document.getElementById('divDataArea');
	elmDiv.innerHTML = '';

	total = 0;

	var arr = GetYearList(data);

	if(ancFlg){
		var elmAncDiv = document.createElement('div');
		elmAncDiv.id ='ancDiv';
		var elmAncUl = document.createElement('ul');
		for(var m in arr){
			var elmAncLi = document.createElement('li');
			var elmAnc = document.createElement('a');
			elmAnc.href = '#ir' + arr[m];
			elmAnc.appendChild(document.createTextNode(SeirekiToWareki(arr[m])));
			elmAncLi.appendChild(elmAnc);
			elmAncUl.appendChild(elmAncLi);
		}
		elmAncDiv.appendChild(elmAncUl);
		elmDiv.appendChild(elmAncDiv);
	}

	for (var year in arr) {
		// メニューリンク、プルダウンの場合は、選択した決算期と一致するデータのみ表示
		if(yearList == 0 || yearList == 1) {
			if (arr[year] != selFy) {
				continue;
			}
		}		

		// 決算期表示
		var elmH3 = document.createElement('h3');
		elmH3.className ='ttl-cmn-03';
		elmH3.id = 'ir' + arr[year];
		elmH3.appendChild(document.createTextNode(SeirekiToWareki(arr[year])));
		elmDiv.appendChild(elmH3);

		for (var i =0;i<data.item_count;i++) {
			if (arr[year] == data.item[i].tanshin_year) {
				// 短信表示

				// 訂正
				if(teiseiFlg) {			
					drawTeiseiData(data, data.item[i], selFy, elmDiv);
				}

				createData(elmDiv, data.item[i]);
				total += 1;
			}
		}
	}

//	}

	// データが１件も存在しない場合
	if (total == 0) {
		elmDl.appendChild(document.createTextNode('掲載情報はございません'));
	}
}


// 適時開示に短信訂正があれば表示する
function drawTeiseiData(data, tanshinItem, selFy, elm) {

	var q;

	if( zen2han(tanshinItem.tanshin_type).match('第1四半期')){
		q = '第1四半期';
	} else if( zen2han(tanshinItem.tanshin_type).match('第2四半期')){
		q = '第2四半期';
	} else if( zen2han(tanshinItem.tanshin_type).match('第3四半期')){
		q = '第3四半期';
	} else if( zen2han(tanshinItem.tanshin_type).match('個別財務諸表')){
		q = '個別財務諸表';
	} else if( zen2han(tanshinItem.tanshin_type).match('個別中間財務諸表')){
		q = '個別中間財務諸表';
	} else if( zen2han(tanshinItem.tanshin_type).match('中間決算')){
		q = '中間決算';
	} else{
		q = '通期';
	}

	for (x = 0; x < data.item.length; x++) {
		if (data.item[x].tanshin_year.length == 0) {
			if (!data.item[x].tanshin_type.match('訂正')){
				continue;
			} else if(!data.item[x].tanshin_type.match('短信')
			 && !data.item[x].tanshin_type.match('財務諸表の概要')
			  && !data.item[x].tanshin_type.match('業績の概況')){
				continue;
			}
		} else if( data.item[x].tanshin_year.length > 0 ){
			continue;
		}

		var title = zen2han(data.item[x].tanshin_type);
		var tit = title;
		if( title.match('年') ){
			title = title.split('年')[0];
			if( title.match('平成') ){
                title = title.split('平成')[1];
                title = Number(title)+1988;
            }
            else if( title.match('令和') && tit.match('元年') ){
                title = 2019;
            }
            else if( title.match('令和') ){
                title = title.split('令和')[1];
                title = Number(title)+2018;
            }
            else if(title.match(/(\d{4})/)){
                title = title.match(/(\d{4})/)[1];
            }
		}

		if(title != tanshinItem.tanshin_year.substr(0,4) ){
			continue;
		}

		if(q == '通期'){
			if(tit.match('第1四半期') || tit.match('第2四半期') || tit.match('第3四半期') || tit.match('個別') || tit.match('中間') ){
				continue;
			}
		} else{
			if(!tit.match(q) ){
				continue;
			}
		}

		createData(elm, data.item[x]);

		total += 1;
	}
}

//------------------------------
// 年月日と加算日からn日後、n日前を求める関数
//------------------------------
function GetComputeDate(DaySpan) {
	myD = new Date();
	myD = new Date(myD.getFullYear(), myD.getMonth(), myD.getDate() + DaySpan);

	myYear = myD.getFullYear();
	myMonth = myD.getMonth() + 1;
	myDate = myD.getDate();

	return myYear.toString() + formatNum(2, myMonth) + formatNum(2, myDate);
}
//------------------------------
// 各表示項目のdateの値(yyyy/MM/dd hh:mm:ss)を
// yyyyMMddにフォーマットして返す関数
//------------------------------
function GetFormatDate(date) {
	return date.substr(0, 4) + date.substr(5, 2) + date.substr(8, 2);
}
//------------------------------
// 表示桁数のフォーマット関数
//------------------------------
function formatNum(keta, num) {
	var src = new String(num);
	var cnt = keta - src.length;
	if (cnt <= 0) return src;
	while (cnt-- > 0) src = "0" + src; return src;
}

//------------------------------
// JSON/Xmlから取得したデータの各項目を表示させる関数
// 表示データ作成(１データ毎)
// 【パラメータ】
// element：
// item：JSON/Xmlデータの各項目(item)
//------------------------------
function createData(element, item) {
	var elmDl = document.createElement('dl');
	element.appendChild(elmDl);

	// <dt>要素を新規に作成する
	var elmDt = document.createElement('dt');
	// 英語短信の場合はクラス付与
	if (item.link_tanshin.length > 0) {
		if(!(item.link_tanshin.match("ir_material_for_fiscal_ym"))){
			// <dt>要素を新規に作成する
			var elmDt = document.createElement('dt');
			// 作成した<dt>要素に各表示項目の「format_date」の値を追加する
			//	if(item.tanshin_type.match('訂正')){
			//		elmDt.className = 'teiseiDt';
			//	}
			elmDt.appendChild(document.createTextNode(item.format_date));
			// パラメータで渡されてきた<dl>要素に<dt>要素を追加する
			elmDl.appendChild(elmDt);
		}
	}

	// <dd>要素を新規に作成する
	var elmDd = document.createElement('dd');

	// 各表示項目の「link_tanshin」の値が設定されている場合は
	// <dd>要素に<a>要素を追加する
	// 「link_tanshin」が設定されていない場合は
	// <dd>要素に各表示項目の「title」の値のみを追加する
	if (item.link_tanshin.length > 0) {
		var elmA = document.createElement('a');
		elmA.href = item.link_tanshin;
		elmA.target = item.new_target;
		elmA.appendChild(document.createTextNode( zen2han(item.tanshin_type) ));
		elmDd.appendChild(elmA);
	} else {
		elmDd.appendChild(document.createTextNode( zen2han(item.tanshin_type) ));
	}

	// ファイルタイプの<img>要素を新規に作成する
	var elmImg = document.createElement('img');
	elmImg.setAttribute("src", "/z0y6LaZKWu/wp-content/themes/corporate2017/ir/parts/img/filetype_icon/pdf.gif");
	elmImg.setAttribute('align', 'absmiddle');
	elmDd.appendChild(elmImg);

	// ファイルサイズあり
	if (item.tanshin_size.length > 0) {
		elmDd.appendChild(document.createTextNode(' [PDF ' + item.tanshin_size + 'KB]'));
	}

	// 新着情報
	// 表示切替フラグがtrueで、かつ新着コンテンツの場合に表示
	var fDate = GetFormatDate(item.date);
	if (NewIconFlg && fDate >= GetComputeDate(NewIconLimit)) {
		var elmImg2 = document.createElement('img');
		elmImg2.setAttribute("src", "/z0y6LaZKWu/wp-content/themes/corporate2017/ir/parts/img/filetype_icon/pdf.gif");
		elmImg2.setAttribute('align', 'absmiddle');
		elmDd.appendChild(elmImg2);
	}

	// コメントが設定されている場合は書き出す
	if (item.comment.length > 0) {
		var elmComment = document.createElement('div');
		elmComment.className = 'comment';
		elmComment.innerHTML = item.comment;
		elmDd.appendChild(elmComment);
	}

	elmDl.appendChild(elmDd);
}


//------------------------------
// 年度選択DropDownListの項目が
// 切り替えられた時のイベントハンドラ
//------------------------------
function selIndex(index) {

	var year = 0;
	// 年度選択DropDownList(<select>要素)をIDの値で検索し、
	// 取得する
	var elmSel = document.getElementById('yearSelect');
	if (elmSel != null && elmSel != undefined) {
		year = elmSel.options[elmSel.selectedIndex].value;
	}

	// 表示データの更新を行う
	drawDataArea(org_data, year);
}

//------------------------------
// JSON・Xmlから取得したデータの
// 年度のリストを取得するためのサポート関数
//------------------------------
function GetYearList(data) {
	// 年度の配列格納用の変数を新規に宣言
	var arr = new Array();

	// JSON(またはXml)のデータをループして、
	// 各データの「date」で指定されている値を取得し、
	// 配列に格納する。
	for (i = 0; i < data.item.length; i++) {
		var year = createTyear(data.item[i]);
		if ((year != "") && (!(year in arr)) ) {
			arr[year] = year;
		}
	}
	arr.reverse();

	return arr;
}
//------------------------------
// 取得した年度のリストから
// 最大(または最小)の年度を取得するためのサポート関数
// 【パラメータ】
// IsMax：最大(または最小)の切り替えフラグ
//------------------------------
function GetMaxOrMinYear(arr, IsMax) {
	if (IsMax) {
		// 年度リストを降順に並びかえ
		arr.reverse();
	} else {
		// 年度リストを昇順に並びかえ
		arr.sort();
	}
	return arr[0];
}
//------------------------------
// 【クロスブラウザ対応】
// 各ブラウザによって、
// 年度選択DropDownListへのイベントの追加方法が違うため、
// それをカバーするサポート関数
// 【パラメータ】
// Target：イベントの追加対象になるElement
// type：イベント名から「on」を除いた名前
// func：イベントが発生した時に実行させる関数
//------------------------------
function addEventListenerIR(target, type, func) {
	if(target.attachEvent) {
		// 【IE対応】イベント追加処理
		target.attachEvent("on" + type, func);
	} else if(target.addEventListener) {
		// 【FireFox対応】イベント追加処理
		target.addEventListener(type, func, true);
	} else {
		//イベントリスナが使えない場合は on○○ 属性を上書き
		target["on" + type] = func;
	}
}


//------------------------------
// 年度選択DropDownListで
// 「最新１年分」が指定されている場合に
// 各データが最新１年のデータかどうか判定するサポート関数
//------------------------------
function IsOneYearAgo(CurDate, CompDate) {
	var y = CompDate.substr(0, 4);
	var m = CompDate.substr(5, 2);
	var d = CompDate.substr(8, 2);

	var year = CurDate.getYear();
	if (year < 2000) year += 1900;
	var mon = CurDate.getMonth() + 1;
	var date = CurDate.getDate();

	NewDate = new Date(year - 1, mon, date);
	if (NewDate <= new Date(y, m, d)) {
		return true;
	}
	return false;
}



