				link_tanshin : org_data_2.group[i].item[j].link,
				new_target : org_data_2.group[i].item[j].new_target,
				tanshin_category : "",
				tanshin_type : org_data_2.group[i].item[j].title,
				comment : org_data_2.group[i].item[j].comment,
				tanshin_size : org_data_2.group[i].item[j].file_size,
				tanshin_year : org_data_2.group[i].fiscal_ym,
				teisei_item : [],
				page_num : org_data_2.group[i].page_num,
				doc_cat : "",
				type : org_data_2.group[i].type,
